export interface Request {
  path: string;
}

export interface Response {
  send(body: unknown): void;
}

export type Handler = (request: Request, response: Response, next: () => void) => void;

/** A router that is itself a handler, so `use` takes one router or middleware alike. */
export interface Router {
  (request: Request, response: Response, next: () => void): void;
  use(path: string, ...handlers: Handler[]): this;
  use(...handlers: Handler[]): this;
  post(path: string, handler: Handler): this;
}

declare function router(): Router;
export default router;
